/** कर्नेल_मान 안의 연결형 बाइट_मान स्ट्रीम_मान. Ethernet/TCP 패킷 스택이 아닌 루프백 socket लेयर_मान. */
public final class स्ट्रीम_नेटवर्क {
    static int[] अवस्था_मान = new int[16], पोर्ट_मान = new int[16], 짝 = new int[16], पीअर_पोर्ट = new int[16], प्रतीक्षा_करें_मान = new int[16], सूचना_प्रौद्योगिकी_सीमा = new int[16];
    static int[] सामने_मान = new int[16], 수 = new int[16], आँकड़े = new int[16 * 1024];
    static int अगला_आइटम = 50000;
    static int सत्यापित_करें(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && अवस्था_मान[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int पोर्ट_संख्या) { for (int लूप_इंडेक्स = 0; लूप_इंडेक्स < 16; लूप_इंडेक्स++) if (अवस्था_मान[लूप_इंडेक्स] != 0 && सूचना_प्रौद्योगिकी_सीमा[लूप_इंडेक्स] != 0 && पोर्ट_मान[लूप_इंडेक्स] == पोर्ट_संख्या) return true; return false; }
    public static int बनाएँ_एन्ट्री() {
        for (int लूप_इंडेक्स = 0; लूप_इंडेक्स < 16; लूप_इंडेक्स++) if (अवस्था_मान[लूप_इंडेक्स] == 0) { अवस्था_मान[लूप_इंडेक्स] = 1; पीअर_पोर्ट[लूप_इंडेक्स] = पोर्ट_मान[लूप_इंडेक्स] = सामने_मान[लूप_इंडेक्स] = 수[लूप_इंडेक्स] = प्रतीक्षा_करें_मान[लूप_इंडेक्स] = सूचना_प्रौद्योगिकी_सीमा[लूप_इंडेक्स] = 0; 짝[लूप_इंडेक्स] = -1; return लूप_इंडेक्स + 40; }
        return -24;
    }
    public static int बाइंड_करें_एंडपॉइंट(int 열린파일번호, int सॉकेट_पता, int पोर्ट_संख्या) {
        int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); if (लूप_इंडेक्स < 0) return -9;
        if (सॉकेट_पता != 0 && सॉकेट_पता != 0x7f000001) return -99;
        if (अवस्था_मान[लूप_इंडेक्स] != 1 || पोर्ट_संख्या < 0 || पोर्ट_संख्या > 65535) return -22;
        if (पोर्ट_संख्या == 0) { do { पोर्ट_संख्या = अगला_आइटम++; if (अगला_आइटम > 65535) अगला_आइटम = 50000; } while (사용중(पोर्ट_संख्या)); }
        if (사용중(पोर्ट_संख्या)) return -98; पोर्ट_मान[लूप_इंडेक्स] = पोर्ट_संख्या; सूचना_प्रौद्योगिकी_सीमा[लूप_इंडेक्स] = 1; अवस्था_मान[लूप_इंडेक्स] = 2; return 0;
    }
    public static int सुनिए_एंडपॉइंट(int 열린파일번호, int कार्य_संचय) { int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); if (लूप_इंडेक्स < 0) return -9; if (अवस्था_मान[लूप_इंडेक्स] != 2 || कार्य_संचय < 1) return -22; अवस्था_मान[लूप_इंडेक्स] = 3; return 0; }
    public static int जोड़ना(int 열린파일번호, int सॉकेट_पता, int पोर्ट_संख्या) {
        int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); if (लूप_इंडेक्स < 0) return -9; if (सॉकेट_पता != 0x7f000001) return -101;
        if (पोर्ट_संख्या < 1 || पोर्ट_संख्या > 65535 || अवस्था_मान[लूप_इंडेक्स] > 2) return -22;
        int 수신쪽 = -1; for (int इनर_पद = 0; इनर_पद < 16; इनर_पद++) if (अवस्था_मान[इनर_पद] == 3 && पोर्ट_मान[इनर_पद] == पोर्ट_संख्या) 수신쪽 = इनर_पद;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int इनर_पद = 0; इनर_पद < 16; इनर_पद++) if (प्रतीक्षा_करें_मान[इनर_पद] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (अवस्था_मान[लूप_इंडेक्स] == 1) { int 처리값 = बाइंड_करें_एंडपॉइंट(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int अदर = बनाएँ_एन्ट्री(); if (अदर < 0) return अदर; अदर -= 40;
        अवस्था_मान[लूप_इंडेक्स] = अवस्था_मान[अदर] = 4; 짝[लूप_इंडेक्स] = अदर; 짝[अदर] = लूप_इंडेक्स; पोर्ट_मान[अदर] = पोर्ट_संख्या; पीअर_पोर्ट[लूप_इंडेक्स] = पोर्ट_संख्या; पीअर_पोर्ट[अदर] = पोर्ट_मान[लूप_इंडेक्स]; प्रतीक्षा_करें_मान[अदर] = 수신쪽 + 1; return 0;
    }
    public static int स्वीकार_करें_कनेक्शन(int 열린파일번호) { int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); if (लूप_इंडेक्स < 0) return -9; if (अवस्था_मान[लूप_इंडेक्स] != 3) return -22; for (int इनर_पद = 0; इनर_पद < 16; इनर_पद++) if (अवस्था_मान[इनर_पद] != 0 && प्रतीक्षा_करें_मान[इनर_पद] == लूप_इंडेक्स + 1) { प्रतीक्षा_करें_मान[इनर_पद] = 0; return इनर_पद + 40; } return -11; }
    public static int लिखें(int 열린파일번호, int 항목수) {
        int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); if (लूप_इंडेक्स < 0) return -9; if (अवस्था_मान[लूप_इंडेक्स] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int इनर_पद = 짝[लूप_इंडेक्स]; if (इनर_पद < 0) return -32; int 총수 = 1024 - 수[इनर_पद]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int तुलना_पद = 0; तुलना_पद < 총수; तुलना_पद++) आँकड़े[इनर_पद * 1024 + (सामने_मान[इनर_पद] + 수[इनर_पद] + तुलना_पद) % 1024] = लूपबैक_नेटवर्क.आगे_मान[तुलना_पद]; 수[इनर_पद] += 총수; return 총수;
    }
    public static int पढ़ें(int 열린파일번호, int 항목수) {
        int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); if (लूप_इंडेक्स < 0) return -9; if (अवस्था_मान[लूप_इंडेक्स] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[लूप_इंडेक्स] == 0) return 짝[लूप_इंडेक्स] < 0 ? 0 : -11; if (항목수 > 수[लूप_इंडेक्स]) 항목수 = 수[लूप_इंडेक्स];
        for (int तुलना_पद = 0; तुलना_पद < 항목수; तुलना_पद++) लूपबैक_नेटवर्क.आगे_मान[तुलना_पद] = आँकड़े[लूप_इंडेक्स * 1024 + (सामने_मान[लूप_इंडेक्स] + तुलना_पद) % 1024]; सामने_मान[लूप_इंडेक्स] = (सामने_मान[लूप_इंडेक्स] + 항목수) % 1024; 수[लूप_इंडेक्स] -= 항목수; return 항목수;
    }
    public static int पढें_एंडपॉइंट_पोर्ट(int 열린파일번호) { int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); return लूप_इंडेक्स < 0 ? -9 : पोर्ट_मान[लूप_इंडेक्स]; }
    public static int पढें_पीअर_पोर्ट(int 열린파일번호) { int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); return लूप_इंडेक्स < 0 ? -9 : पीअर_पोर्ट[लूप_इंडेक्स]; }
    public static int बंदकरें(int 열린파일번호) {
        int लूप_इंडेक्स = सत्यापित_करें(열린파일번호); if (लूप_इंडेक्स < 0) return -9;
        if (अवस्था_मान[लूप_इंडेक्स] == 3) for (int इनर_पद = 0; इनर_पद < 16; इनर_पद++) if (प्रतीक्षा_करें_मान[इनर_पद] == लूप_इंडेक्स + 1) { if (짝[इनर_पद] >= 0) 짝[짝[इनर_पद]] = -1; अवस्था_मान[इनर_पद] = प्रतीक्षा_करें_मान[इनर_पद] = सूचना_प्रौद्योगिकी_सीमा[इनर_पद] = 0; }
        if (짝[लूप_इंडेक्स] >= 0) 짝[짝[लूप_इंडेक्स]] = -1; अवस्था_मान[लूप_इंडेक्स] = सूचना_प्रौद्योगिकी_सीमा[लूप_इंडेक्स] = 수[लूप_इंडेक्स] = प्रतीक्षा_करें_मान[लूप_इंडेक्स] = 0; return 0;
    }
}
